def load() -> pd.DataFrame:
    import glob, pandas as pd
    paths = [
        'data/astronomy/input/geomag_forecast/0309geomag_forecast.txt',
        'data/astronomy/input/geomag_forecast/0311geomag_forecast.txt',
        'data/astronomy/input/geomag_forecast/0312geomag_forecast.txt',
        'data/astronomy/input/geomag_forecast/0313geomag_forecast.txt',
    ]
    rows = []
    for p in paths:
        for fp in glob.glob(p):
            with open(fp, 'r', encoding='utf-8', errors='replace') as f:
                rows.append({'path': fp, 'text': f.read()})
    return pd.DataFrame(rows)

def process(geomag_files):
    import pandas as pd, re
    rows=[]
    for _,r in geomag_files.iterrows():
        path=r['path']
        text=r['text']
        m=re.search(r":Issued:\s*(\d{4} \w{3} \d{2})", text)
        issued=pd.to_datetime(m.group(1)) if m else pd.NaT
        for typ in ['Observed','Estimated','Predicted']:
            for mm in re.finditer(rf"^{typ} Ap\s+(.+)$", text, flags=re.M):
                line=mm.group(0)
                rest=mm.group(1).strip()
                rows.append({'path':path,'issued_date':issued,'type':typ,'raw':line,'rest':rest})
    return pd.DataFrame(rows)
